
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_pi_m06_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_pi_m06_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.628169445478166e-02, -6.596673984563599e-02, -6.548884544537591e-02, -6.474546728269334e-02, -6.354706631454603e-02, -6.151983419134036e-02, -5.790193227819408e-02, -5.130998617442089e-02, -4.100475097210443e-02, -3.506029387264092e-02, -4.336677307036647e-02, -7.929170221307251e-02, -2.729194500923185e-02, -2.311286840358267e-02, -1.726684934471742e-02, -1.588121247850726e-02, 1.197674405367226e-02, 6.363318305480608e-03, 7.850504677705818e-04, 3.721342129091080e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


